/**
 * Enhanced Hotspot Cookie & Card Wallet Persistent Storage Engine
 * Keeps cards securely saved in localStorage and 10-year Cookies for the Wallet list,
 * while keeping the active login input clean and empty on logout / disconnect.
 */

var HOT_COOKIE_KEY = 'alkary_vouchers';
var HOT_ACTIVE_KEY = 'alkary_active_voucher';
var HOT_COOKIE_EXPIRE_DAYS = 3650; // 10 years

// 1. Cookie Helper Functions with Domain-Wide & Cross-Subnet compatibility
function setHotCookie(name, value, days) {
    try {
        var d = new Date();
        d.setTime(d.getTime() + ((days || HOT_COOKIE_EXPIRE_DAYS) * 24 * 60 * 60 * 1000));
        var expires = "expires=" + d.toUTCString();
        var encodedVal = encodeURIComponent(value);

        // Standard path cookie
        document.cookie = name + "=" + encodedVal + ";" + expires + ";path=/;SameSite=Lax";

        // Domain-wide cookie for hotspot domains like c.net
        var host = window.location.hostname || '';
        if (host && host.indexOf('.') !== -1 && !/^\d+\.\d+\.\d+\.\d+$/.test(host)) {
            if (host.indexOf('c.net') !== -1) {
                document.cookie = name + "=" + encodedVal + ";" + expires + ";path=/;domain=.c.net;SameSite=Lax";
            }
        }
    } catch (e) {}
}

function getHotCookie(name) {
    try {
        var cname = name + "=";
        var decodedCookie = decodeURIComponent(document.cookie);
        var ca = decodedCookie.split(';');
        for (var i = 0; i < ca.length; i++) {
            var c = ca[i].trim();
            if (c.indexOf(cname) === 0) {
                return c.substring(cname.length, c.length);
            }
        }
    } catch (e) {}
    return "";
}

// 2. Multi-Tier Voucher List Sync & Storage
function getSavedVouchersList() {
    if (window.AlkaryWallet && Array.isArray(window.AlkaryWallet.cards) && window.AlkaryWallet.cards.length > 0) {
        return window.AlkaryWallet.cards;
    }

    var list = [];

    // Tier 1: LocalStorage
    try {
        var localData = localStorage.getItem(HOT_COOKIE_KEY) || localStorage.getItem('alkary_vouchers_backup') || localStorage.getItem('alkary_saved_wallet');
        if (localData) {
            var parsed = JSON.parse(localData);
            if (Array.isArray(parsed)) list = list.concat(parsed);
        }
    } catch (e) {}

    // Tier 2: SessionStorage
    try {
        var sessData = sessionStorage.getItem(HOT_COOKIE_KEY);
        if (sessData) {
            var parsedSess = JSON.parse(sessData);
            if (Array.isArray(parsedSess)) list = list.concat(parsedSess);
        }
    } catch (e) {}

    // Tier 3: Active Vouchers
    try {
        var act1 = localStorage.getItem('alkary_active_voucher') || localStorage.getItem('alkary_active_user');
        if (act1) list.push(act1);
    } catch (e) {}

    // Tier 4: Long-Lived Cookies
    try {
        var cookieListRaw = getHotCookie(HOT_COOKIE_KEY) || getHotCookie('alkary_cards_wallet');
        if (cookieListRaw) {
            var parsedCookie = JSON.parse(cookieListRaw);
            if (Array.isArray(parsedCookie)) list = list.concat(parsedCookie);
        }
        var unameCookie = getHotCookie('uname') || getHotCookie('username');
        if (unameCookie && unameCookie !== '100' && unameCookie.indexOf('$') === -1) {
            list.push(unameCookie);
        }
    } catch (e) {}

    // Clean & Deduplicate
    var cleanList = [];
    list.forEach(function(item) {
        var code = String(item || '').trim();
        if (code && code !== '100' && code.indexOf('$') === -1 && cleanList.indexOf(code) === -1) {
            cleanList.push(code);
        }
    });

    if (cleanList.length > 0) {
        try {
            localStorage.setItem(HOT_COOKIE_KEY, JSON.stringify(cleanList));
            setHotCookie(HOT_COOKIE_KEY, JSON.stringify(cleanList), HOT_COOKIE_EXPIRE_DAYS);
        } catch(e) {}
    }

    return cleanList;
}

function saveVoucherToStorage(code) {
    if (!code) return;
    code = String(code).trim();
    if (!code || code === '$(username)' || code === '100' || code.indexOf('$') !== -1) return;

    if (window.AlkaryWallet && typeof window.AlkaryWallet.saveCard === 'function') {
        window.AlkaryWallet.saveCard(code);
        return;
    }

    try {
        var list = getSavedVouchersList();
        var idx = list.indexOf(code);
        if (idx !== -1) {
            list.splice(idx, 1);
        }
        list.unshift(code);
        if (list.length > 25) list.pop();

        var json = JSON.stringify(list);
        try { localStorage.setItem(HOT_COOKIE_KEY, json); } catch (e) {}
        try { localStorage.setItem('alkary_vouchers_backup', json); } catch (e) {}
        try { localStorage.setItem('alkary_active_voucher', code); } catch (e) {}
        try { sessionStorage.setItem(HOT_COOKIE_KEY, json); } catch (e) {}

        setHotCookie(HOT_COOKIE_KEY, json, HOT_COOKIE_EXPIRE_DAYS);
        setHotCookie('alkary_cards_wallet', json, HOT_COOKIE_EXPIRE_DAYS);
        setHotCookie('uname', code, HOT_COOKIE_EXPIRE_DAYS);

        if (typeof updateHistoryCount === 'function') updateHistoryCount();
    } catch (e) {}
}

function rem() {
    var unameEl = document.getElementById('uname');
    var remEl = document.getElementById('remember');
    if (!unameEl) return;

    var uname = unameEl.value ? unameEl.value.trim() : '';
    var isRemember = remEl ? remEl.checked : true;

    if (uname && (isRemember || isRemember === undefined)) {
        saveVoucherToStorage(uname);
    }
}

function getCookie() {
    var unameEl = document.getElementById('uname');
    var paswdEl = document.getElementById('paswd');
    if (unameEl) {
        unameEl.value = "";
    }
    if (paswdEl) {
        paswdEl.value = "";
    }

    if (typeof updateHistoryCount === 'function') {
        updateHistoryCount();
    }
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', getCookie);
} else {
    getCookie();
}

